package com.talkbot.plugin.listener;
import com.talkbot.plugin.TalkBotPlugin;import com.talkbot.plugin.manager.ChatManager;import org.bukkit.Bukkit;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.player.*;import org.bukkit.event.entity.*;import org.bukkit.block.Block;import org.bukkit.Material;import java.util.*;
@SuppressWarnings("deprecation") public final class ChatListener implements Listener {
 private final TalkBotPlugin plugin;private final ChatManager chat;
 public ChatListener(TalkBotPlugin p,ChatManager c){plugin=p;chat=c;}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void onChat(AsyncPlayerChatEvent e){Player p=e.getPlayer();String message=e.getMessage();Bukkit.getScheduler().runTask(plugin,()->{if(plugin.getBotRegistry().isBot(p.getName()))chat.handleBotMessage(p,message);else chat.handlePlayerMessage(p,message);});}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void onWhisperCommand(PlayerCommandPreprocessEvent e){String raw=e.getMessage().substring(1);String[] a=raw.split("\s+",3);if(a.length<3)return;List<String> aliases=new ArrayList<>(plugin.getConfig().getStringList("chat.whisper-aliases"));aliases.add(plugin.getConfig().getString("chat.whisper-command","whisper"));if(aliases.stream().noneMatch(x->x.equalsIgnoreCase(a[0])))return;chat.handleWhisper(e.getPlayer(),a[1],a[2]);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void onDamage(EntityDamageEvent e){if(!(e.getEntity() instanceof Player p)||!plugin.getBotRegistry().isBot(p.getName()))return;boolean visible=p.getNearbyEntities(8,5,8).stream().anyMatch(x->x instanceof Player||x instanceof org.bukkit.entity.Monster);if(!visible)Bukkit.getScheduler().runTask(plugin,()->chat.onDamage(p,false));if(p.getHealth()-e.getFinalDamage()<=3.0)Bukkit.getScheduler().runTask(plugin,()->chat.onLowHealth(p));}
 @EventHandler public void onDeath(PlayerDeathEvent e){if(plugin.getBotRegistry().isBot(e.getEntity().getName()))Bukkit.getScheduler().runTask(plugin,()->chat.onDeath(e.getEntity()));}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void onPlace(org.bukkit.event.block.BlockPlaceEvent e){Player p=e.getPlayer();if(!plugin.getBotRegistry().isBot(p.getName()))return;Material m=e.getBlockPlaced().getType();if(plugin.getConfig().getStringList("chat.mole-materials").contains(m.name()))Bukkit.getScheduler().runTask(plugin,()->chat.onMole(p,m.name()));}
}
